// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(uint256 lockBlockOffset) public {
        // Admissible domain: a player locks a guess in some future block, waits,
        // and tries to claim.  The guess is the hash the reference will compute
        // from a future blockhash.  Negative or zero offsets are not useful.
        uint256 offset = bound(lockBlockOffset, 1, 100);

        address player = address(0xBEEF);
        vm.deal(player, 1 ether);

        // Advance the chain so the player is not at the constructor block in a weird way.
        vm.roll(block.number + offset);

        // The player uses the public surface: lockInGuess with the answer that
        // the reference will compute after one more block, i.e. the blockhash
        // of the block in which the guess is stored.  We can choose the guess
        // freely; the reference accepts it.  To make the reference pay, the
        // guess must equal the blockhash of the block after the settle call's
        // current block?  Actually lockInGuess stores block.number + 1, so
        // after one block the reference hashes that stored block number.
        // We pick the guess as the hash of the blockhash of that stored block.
        // Since the stored block is block.number + 1 at lock time, we can
        // compute the future blockhash only if we know it; however the point
        // of the fuzz test is not to predict a real blockhash (which is
        // impossible), but to assert the general rule that the reference pays
        // exactly 2 ether if the guess equals the answer and otherwise keeps
        // the funds.  The known failing tests tried to precompute the hash.
        //
        // We avoid that by instead asserting an invariant that holds for any
        // guess: the contract's balance after settle is either 2 ether (paid
        // out, guess was correct) or 3 ether (not paid), but never 4 ether
        // (constructor 1 + lock 1 + remaining 2? no) -- the reference always
        // pays 2 ether only when the guess matches.  The bug hashes the block
        // number, so for a guess of keccak256(abi.encodePacked(blockhash(stored)))
        // the reference can pay while the mutant cannot.  But blockhash for
        // future blocks is zero in test?  In Foundry, blockhash of recent
        // blocks returns 0 unless the block is in the last 256 blocks and
        // actually mined.  This is the root of the earlier failures: the
        // reference cannot pay unless the guess equals keccak256(blockhash(blockNum)),
        // and blockhash(blockNum) is address(0) for a future block <= 256 back?
        // Actually blockhash returns 0 for the current block or future blocks.
        // So if we set the guess to keccak256(abi.encodePacked(bytes32(0))), the
        // reference will pay because blockhash(storedBlock) == 0 as long as
        // the stored block is not yet mined at the time of the guess?  No,
        // after rolling forward one block, blockhash(storedBlock) will be
        // nonzero if the stored block is in the past.  But we can make the
        // stored block be the current block at settle so blockhash is 0?
        // The require block.number > stored ensures stored is a past block.
        // blockhash of a past block within 256 is nonzero.
        // So we cannot force the reference to pay with a known hash without
        // knowing the future blockhash.  The earlier tests failed because they
        // tried to precompute the hash.  We instead assert a property about
        // the balance after settle: the contract never pays out more than 2 ether,
        // and the mutant's balance differs when the reference would have paid.
        // But since we cannot know the blockhash in advance, we cannot guarantee
        // the reference pays.  Yet the mutant hashes block.number (a small
        // integer) and the guess is bytes32 -- the probability of matching is
        // negligible.  The reference, on the other hand, hashes a real blockhash
        // chosen at settle time, so a player who sets guess = keccak256(blockhash(stored))
        // cannot know it in advance.  The game is a gambling game: the player
        // cannot predict the blockhash.  So the reference almost never pays
        // either.  The difference is that the reference's answer depends on the
        // unpredictable blockhash, making it impossible to precompute, while the
        // mutant's answer depends only on block.number, which is public and
        // known.  Therefore the correct rule is about the ability of an
        // attacker to predict the answer before the settle block.  Specifically:
        // in the reference, after locking, the answer is not determined by
        // information available at lock time (because blockhash(stored) is
        // unknown), so the player's guess cannot be set to the answer in
        // advance with certainty.  In the mutant, the answer is known at lock
        // time (it's keccak256(block.number + 1)), so a player can set their
        // guess to exactly that and guarantee a payout.  The reference cannot
        // be exploited this way.  This is the invariant:
        //   For any guess, the reference pays only if the guess equals the
        //   hash of the stored block's blockhash, which is unknown at lock
        //   time.  The mutant pays if the guess equals hash(block.number+1),
        //   which anyone can compute.  Thus an attacker who sets
        //   guess = keccak256(abi.encodePacked(uint256(block.number+1))) will
        //   win on the mutant but lose on the reference (with overwhelming
        //   probability, since the reference's answer is a blockhash).
        //
        // To test this without relying on blockhash being nonzero/predictable,
        // we exploit the fact that in Foundry, blockhash of a future block is
        // 0.  The stored block is block.number + 1 at lock time.  At settle
        // time after rolling forward by one, the stored block is the previous
        // block.  Is blockhash of the previous block zero?  No, it's the hash
        // of that block.  But we can call settle in the SAME block if we
        // bypass the require?  No, require block.number > stored.
        // Alternative: we set the stored block to a block whose blockhash is
        // known to be zero: if the stored block is more than 256 blocks ago,
        // blockhash returns 0.  Can we make stored be more than 256 blocks
        // behind?  lockInGuess sets stored = block.number + 1.  If we lock,
        // then roll forward 300 blocks, then settle, the stored block is 300
        // blocks past, blockhash returns 0.  Then the reference answer is
        // keccak256(abi.encodePacked(bytes32(0))).  That is predictable!
        // So an attacker can lock with that guess, roll forward >256 blocks,
        // and settle to win on the reference too.  Hmm, that means the
        // reference is also exploitable in test environment.  The original
        // tests failed because they did not account for this?  Actually the
        // earlier tests probably set guess to keccak256(abi.encodePacked(blockhash(stored)))
        // and then settled in the next block, where blockhash(stored) is
        // nonzero, so the guess didn't match.  The fix is to roll forward
        // more than 256 blocks so blockhash(stored) is zero, making the guess
        // predictable and the reference pays.  The mutant still doesn't pay
        // because it hashes block.number (the stored block number, which is
        // not zero).  So the general rule: after an attacker guesses
        // keccak256(abi.encodePacked(bytes32(0))) and settles after >256
        // blocks, the reference pays 2 ether and the mutant does not.

        // We'll implement that.  Fuzz the initial block number / offset within
        // wide range.
        vm.roll(block.number + offset);

        // Guess for the reference when blockhash(stored) will be zero:
        // stored = block.number + 1 at lock time.  After rolling >256, blockhash(stored) == 0.
        // So guess = keccak256(abi.encodePacked(bytes32(0))).
        bytes32 guess = keccak256(abi.encodePacked(bytes32(0)));

        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // Roll forward more than 256 blocks to make blockhash(stored) zero.
        vm.roll(block.number + 300);

        uint256 balanceBefore = address(c).balance; // should be 2 ether
        vm.prank(player);
        c.settle();
        uint256 balanceAfter = address(c).balance;

        // General rule: after lock + settle in this admissible scenario,
        // the reference pays out 2 ether, leaving the contract with 0 ether
        // (balanceBefore - 2 ether).  The mutant does not pay, leaving
        // 2 ether.  So balanceAfter == 0 for reference, != 0 for mutant.
        assertTrue(balanceAfter == balanceBefore - 2 ether);
    }
}
